using RoguePrince.CheatMenu;
using MotherBase.ApplicationFlowManager;
using UnityEngine;
var passed=0;var failed=0;
void Check(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.GetBaseException().Message);}}
void Eq<T>(T a,T b){if(!Equals(a,b))throw new Exception($"expected {b}, got {a}");}
void Refused(Action action){var refused=false;try{action();}catch(InvalidOperationException){refused=true;}catch(ArgumentException){refused=true;}Eq(refused,true);}
(RunRestartActions action,RunTools tools,GameSession game,ApplicationFlowService flow,PauseUIView pause,ApplicationState hub,ApplicationState first) Setup()
{
 Time.timeScale=1;Time.realtimeSinceStartup=0;Application.isFocused=true;RunTools.RunId=4;RunTools.Available=RunRestartActions.Available=true;
 var game=new GameSession();var tools=new RunTools();var flow=new ApplicationFlowService{Pointer=(IntPtr)10,state=new("old")};var hub=new ApplicationState("hub",hub:true);var first=new ApplicationState("first",start:true);foreach(var s in new[]{flow.state,hub,first})flow.states[s.guid]=s;
 var signal=new ApplicationSignal(80);flow.profile.transitions.Add(new(){currentState=hub,nextState=first,signal=signal});flow.exits[80]=first;SceneActions.flow=flow;
 var pause=new PauseUIView{Pointer=(IntPtr)60};Resources.views=new(){pause};return(new(game,tools),tools,game,flow,pause,hub,first);
}
void Hub(ApplicationFlowService f,ApplicationState h){f.state=h;f.IsRunActive=false;f.level=new(){Pointer=(IntPtr)40};}
void Generate(RunRestartActions a,RunTools t,ApplicationFlowService f,ApplicationState first)
{f.state=first;f.IsRunActive=true;t.ResetRun(f);t.Loading(f,first);var p=new LevelGeneratorParameters{stateId=first.stateID,seed=123};t.Prepare(p);a.Generated(p);f.level=new(){Pointer=(IntPtr)50};}
Check("native restart calls give-up once then accepted start signal and confirms new generation",()=>{var(a,t,g,f,p,h,s)=Setup();a.Start("42","2",true,()=>{});Eq(p.onGiveUpConfirmed.calls,1);Eq(a.Busy,true);a.Tick();Eq(f.sends,0);Hub(f,h);f.onSend=()=>Generate(a,t,f,s);a.Tick();Eq(f.sends,1);a.Tick();Eq(a.Busy,false);Eq(a.Error,false);Eq(f.seed,42);Eq(t.ActiveDifficulty,2);});
Check("restart native give-up exception retains observation and never retries",()=>{var(a,t,g,f,p,h,s)=Setup();p.onGiveUpConfirmed.action=()=>{g.Ready=false;throw new Exception("after death");};Refused(()=>a.Start("42","0",false,()=>{}));Eq(a.Busy,true);Eq(p.onGiveUpConfirmed.calls,1);a.Tick();Eq(p.onGiveUpConfirmed.calls,1);g.Ready=true;Hub(f,h);f.onSend=()=>Generate(a,t,f,s);a.Tick();a.Tick();Eq(a.Busy,false);Eq(f.sends,1);});
Check("start signal exception cannot cause a second send",()=>{var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Hub(f,h);f.onSend=()=>{Generate(a,t,f,s);throw new Exception("after loading");};a.Tick();Eq(f.sends,1);a.Tick();Eq(f.sends,1);Eq(a.Busy,false);});
Check("native event missing listeners refuses before reserving or giving up",()=>{var(a,t,g,f,p,h,s)=Setup();p.onGiveUpConfirmed.listeners=0;Refused(()=>a.Start("42","0",false,()=>{}));Eq(p.onGiveUpConfirmed.calls,0);Eq(t.SeedPending,false);});
Check("unloaded or ambiguous pause resources refuse without side effects",()=>{foreach(var ambiguous in new[]{false,true}){var(a,t,g,f,p,h,s)=Setup();if(ambiguous)Resources.views.Add(new(){Pointer=(IntPtr)61});else p.gameObject.scene.isLoaded=false;Refused(()=>a.Start("42","0",false,()=>{}));Eq(p.onGiveUpConfirmed.calls,0);}});
Check("missing native start route refuses before give-up",()=>{var(a,t,g,f,p,h,s)=Setup();f.profile.transitions.Clear();Refused(()=>a.Start("42","0",false,()=>{}));Eq(p.onGiveUpConfirmed.calls,0);});
Check("hub tutorial or loading origin refuses before give-up",()=>{for(int i=0;i<3;i++){var(a,t,g,f,p,h,s)=Setup();if(i==0)f.state=h;if(i==1)((BluesteakApplicationStateLogic)f.state.stateLogic).isTutorialBiome=true;if(i==2)f.isLoading=true;Refused(()=>a.Start("42","0",false,()=>{}));Eq(p.onGiveUpConfirmed.calls,0);}});
Check("invalid seed or awakening never calls native give-up",()=>{foreach(var row in new[]{("NaN","0"),("42","5")}){var(a,t,g,f,p,h,s)=Setup();Refused(()=>a.Start(row.Item1,row.Item2,true,()=>{}));Eq(p.onGiveUpConfirmed.calls,0);}});
Check("existing seed or encounter reservation is not overwritten",()=>{var(a,t,g,f,p,h,s)=Setup();t.Arm("7","1",true);Refused(()=>a.Start("42","0",false,()=>{}));Eq(p.onGiveUpConfirmed.calls,0);Eq(t.SeedPending,true);f.state=s;t.ResetRun(f);var q=new LevelGeneratorParameters{stateId=s.stateID,seed=123};t.Prepare(q);Eq(q.seed,7);});
Check("release callback owner change and remaining pause refuse before event",()=>{foreach(var paused in new[]{false,true}){var(a,t,g,f,p,h,s)=Setup();Refused(()=>a.Start("42","0",false,()=>{if(paused)Time.timeScale=0;else f.level=new(){Pointer=(IntPtr)99};}));Eq(p.onGiveUpConfirmed.calls,0);Eq(t.SeedPending,false);}});
Check("duplicate restart request does not repeat native give-up",()=>{var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Refused(()=>a.Start("42","0",false,()=>{}));Eq(p.onGiveUpConfirmed.calls,1);});
Check("focus loss cancels owned reservation but does not undo give-up",()=>{var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Application.isFocused=false;a.Tick();Eq(a.Busy,false);Eq(t.SeedPending,false);Eq(p.onGiveUpConfirmed.calls,1);Eq(f.sends,0);});
Check("another manager or player saver cancels before sending",()=>{foreach(var saver in new[]{false,true}){var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Hub(f,h);if(saver)g.Saver=new(){Pointer=(IntPtr)22};else SceneActions.flow=new(){Pointer=(IntPtr)11};a.Tick();Eq(a.Busy,false);Eq(f.sends,0);}});
Check("dead loading or paused hub cannot send the start signal",()=>{for(int i=0;i<3;i++){var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Hub(f,h);if(i==0)g.Ready=false;if(i==1)f.isLoading=true;if(i==2)Time.timeScale=0;a.Tick();Eq(f.sends,0);Eq(a.Busy,true);}});
Check("ambiguous or rejected hub exit cancels with no direct scene load",()=>{foreach(var ambiguous in new[]{false,true}){var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Hub(f,h);if(ambiguous){var sig=new ApplicationSignal(81);f.profile.transitions.Add(new(){currentState=h,nextState=s,signal=sig});f.exits[81]=s;}else f.exits.Clear();a.Tick();Eq(a.Busy,false);Eq(a.Error,true);Eq(f.sends,0);}});
Check("generation seed mismatch or unconsumed reservation is not success",()=>{foreach(var wrongSeed in new[]{false,true}){var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Hub(f,h);f.onSend=()=>{f.state=s;f.IsRunActive=true;t.ResetRun(f);if(wrongSeed)t.CancelStart();var q=new LevelGeneratorParameters{stateId=s.stateID,seed=123};if(wrongSeed){}else t.Prepare(q);if(!wrongSeed)q.seed=43;a.Generated(q);};a.Tick();Eq(a.Busy,false);Eq(a.Error,true);}});
Check("cancel only cancels its own seed reservation",()=>{var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});t.Arm("7","0",false);a.Cancel();Eq(t.SeedPending,true);Eq(p.onGiveUpConfirmed.calls,1);});
Check("timeout stops before another native request",()=>{var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Time.realtimeSinceStartup=120;a.Tick();Eq(a.Busy,false);Eq(t.SeedPending,false);Eq(p.onGiveUpConfirmed.calls,1);Eq(f.sends,0);});
Check("new-run reset without generated receipt cannot report completion",()=>{var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Hub(f,h);f.onSend=()=>{f.state=s;f.IsRunActive=true;RunTools.RunId++;f.seed=42;f.level=new(){Pointer=(IntPtr)50};};a.Tick();a.Tick();Eq(a.Busy,true);});
Check("same native seed with failed reservation apply cannot report successful consumption",()=>{var(a,t,g,f,p,h,s)=Setup();f.seed=42;a.Start("42","0",false,()=>{});Hub(f,h);f.onSend=()=>{f.failSeedWrites=true;f.state=s;f.IsRunActive=true;t.ResetRun(f);t.Loading(f,s);var q=new LevelGeneratorParameters{stateId=s.stateID,seed=42};t.Prepare(q);a.Generated(q);f.level=new(){Pointer=(IntPtr)50};};a.Tick();a.Tick();Eq(a.Busy,false);Eq(a.Error,true);Eq(t.SeedPending,false);});
Check("new generated map with no active run cannot report restart completion",()=>{var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Hub(f,h);f.onSend=()=>{Generate(a,t,f,s);f.IsRunActive=false;};a.Tick();a.Tick();Eq(a.Busy,true);Eq(a.Error,false);f.IsRunActive=true;a.Tick();Eq(a.Busy,false);Eq(a.Error,false);});
Check("scene patch disable invalidates a previously applied restart receipt",()=>{var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Hub(f,h);f.onSend=()=>{Generate(a,t,f,s);t.Disable();};a.Tick();a.Tick();Eq(a.Busy,false);Eq(a.Error,true);Eq(f.sends,1);});
Check("a later native reset cannot reuse an old successful reservation receipt",()=>{var(a,t,g,f,p,h,s)=Setup();a.Start("42","0",false,()=>{});Hub(f,h);f.onSend=()=>{Generate(a,t,f,s);t.ResetRun(f);a.Generated(new(){stateId=s.stateID,seed=42});};a.Tick();a.Tick();Eq(a.Busy,false);Eq(a.Error,true);Eq(f.sends,1);});
Console.WriteLine($"RESULT {passed} passed, {failed} failed");return failed==0?0:1;
